  "patch-service-application-by-service-and-app-uuid": {
    summary: "Update service application",
    params: [
      {
        name: "uuid",
        in: "path",
        required: true,
        type: "string",
        description: "Service UUID.",
      },
      {
        name: "app_uuid",
        in: "path",
        required: true,
        type: "string",
        description: "Service application UUID.",
      },
      {
        name: "force_domain_override",
        in: "query",
        required: false,
        type: "boolean",
        description:
          "When true, allow duplicate URLs in the request and proceed despite domain conflicts (same as service PATCH).",
      },
    ],
    body: [
      {
        name: "url",
        type: "string",
        required: false,
        description:
          'Comma-separated list of URLs (e.g. "http://app.example.com:8080,https://app2.example.com"). Stored as fqdn.',
      },
      {
        name: "noindex_domains",
        type: "array",
        required: false,
        description:
          "The subset of the service application domains served with an X-Robots-Tag: noindex, nofollow response header, keeping them out of search engines. Entries that are not among the domains are ignored.",
      },
      { name: "human_name", type: "string", required: false },
      { name: "description", type: "string", required: false },
      { name: "image", type: "string", required: false },
      { name: "exclude_from_status", type: "boolean", required: false },
      { name: "is_log_drain_enabled", type: "boolean", required: false },
      { name: "is_gzip_enabled", type: "boolean", required: false },
      {
        name: "traefik_certificate_resolver",
        type: "string",
        required: false,
        description:
          'Traefik certificate resolver for this service application. Null uses the server setting, "none" uses no resolver.',
      },
      { name: "is_stripprefix_enabled", type: "boolean", required: false },
      { name: "is_force_https_enabled", type: "boolean", required: false },
      {
        name: "is_permanent_redirect_enabled",
        type: "boolean",
        required: false,
        description:
          "Use permanent redirects (301/308) instead of temporary (302/307) for the HTTP to HTTPS and www redirects. Defaults to false.",
      },
      {
        name: "redirect",
        type: "string",
        required: false,
        description:
          'How to handle www and non-www domains. "www" redirects non-www to www, "non-www" redirects www to non-www. Both need a www and a non-www domain in url.',
      },
      {
        name: "max_restart_count",
        type: "integer",
        required: false,
        description:
          "Maximum Docker restart count before Coolify stops the container. Set to 0 to disable the limit.",
      },
    ],
  },
